const handleLogout = async () => {
    try {
      // Logout logic, call API or just clear data
      localStorage.removeItem('token');
      sessionStorage.removeItem('token');
      deleteCookie('token'); // Clear token from cookies if applicable
  
      // Clear other sensitive user data if needed
      localStorage.removeItem('userInfo');
      sessionStorage.removeItem('userInfo');
      deleteCookie('userInfo');
  
      // Optional: Reset any global state (e.g., using Redux or Context API)
      // dispatch(logoutAction()); // If using Redux or similar state management
  
      // Redirect to login page
      navigate('/login'); // Navigate to the login page after logout
    } catch (error) {
      console.error('Logout failed:', error);
      alert('Error logging out. Please try again.');
    }
  };
